  play: async ({
    canvasElement,
    args
  }) => {
    const canvas = within(canvasElement);
    const trigger = canvas.getByRole('combobox');
    await userEvent.click(trigger);
    await expect(trigger).toHaveAttribute('aria-expanded', 'true');

    // The listbox is portalled outside canvasElement, so query the document.
    const listbox = within(document.body).getByRole('listbox');
    await userEvent.click(within(listbox).getByRole('option', {
      name: 'Team'
    }));
    await expect(args['onUpdate:modelValue']).toHaveBeenCalledWith('team');
    // Focus must return to the trigger, or the keyboard user is stranded.
    await expect(trigger).toHaveFocus();
  }
